10	 * Included Files
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	
15	#include <stdint.h>
16	
17	#include <arch/chip/bk7258_amp.h>
18	
19	#include "arm_internal.h"
20	
21	/****************************************************************************
22	 * Pre-processor Definitions
23	 ****************************************************************************/
24	
25	#define BK7258_SCB_CFSR          (*(volatile uint32_t *)0xe000ed28u)
26	#define BK7258_SCB_HFSR          (*(volatile uint32_t *)0xe000ed2cu)
27	#define BK7258_SCB_MMFAR         (*(volatile uint32_t *)0xe000ed34u)
28	#define BK7258_SCB_BFAR          (*(volatile uint32_t *)0xe000ed38u)
29	
30	#define BK7258_EXCEPTION_NMI              2u
31	#define BK7258_EXCEPTION_HARDFAULT        3u
32	#define BK7258_EXCEPTION_FRAME_WORDS      8u
33	#define BK7258_EXCEPTION_FP_FRAME_WORDS   18u
34	#define BK7258_EXC_RETURN_BASIC_FRAME     (1u << 4)
35	#define BK7258_FAULT_INVALID_VALUE        UINT32_MAX
36	
37	/* Match the common ARM vector contract: Thread mode starts on the IDLE
38	 * stack, while arm_initialize_stack() moves handler mode to the dedicated
39	 * interrupt stack before entering __start().
40	 */
41	
42	#define BK7258_AP_IDLE_STACK              \
43	  (_ebss + CONFIG_IDLETHREAD_STACKSIZE)
44	
45	/****************************************************************************
46	 * External Function Prototypes
47	 ****************************************************************************/
48	
49	extern void exception_common(void);
50	extern void __start(void);
51	
52	/****************************************************************************
53	 * Private Functions
54	 ****************************************************************************/
55	
56	static void bk7258_ap_reset_entry(void)
57	{
58	  /* Follow the common ARM reset wrapper before entering board __start:
59	   * preserve the reset stack as PSP for the IDLE thread, switch MSP to the
60	   * dedicated interrupt stack, and terminate the backtrace chain at LR=0.
61	   */
62	
63	  arm_initialize_stack();
64	
65	  __asm volatile ("mov lr, %0\n\t"
66	                  "bx %1\n\t"
67	                  :
68	                  : "r"(0), "r"(__start));
69	}
70	
71	static inline void bk7258_ap_fault_doorbell(uint32_t event,
72	                                            uint32_t error)
73	{
74	  volatile uint32_t *mbox =
75	    (volatile uint32_t *)(uintptr_t)BK7258_MBOX1_BASE;
76	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
77	
78	  state->state      = BK7258_AP_STATE_FAILED;
79	  state->error      = error;
80	  state->last_event = event;
81	
82	  mbox[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
83	  mbox[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
84	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
85	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
86	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
87	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->state;
88	  __asm volatile ("dmb sy" ::: "memory");
89	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
90	  __asm volatile ("dsb sy; isb sy" ::: "memory");
91	}
92	
93	static void __attribute__((noinline, noreturn, used))
94	bk7258_ap_fault_handler(uint32_t *stack, uint32_t exc_return,
95	                        uint32_t exception)
96	{
97	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
98	  volatile struct bk7258_ap_fault_state_s *fault = bk7258_ap_fault_state();
99	  uintptr_t frame_addr = (uintptr_t)stack;
100	  const volatile uint32_t *frame;
101	  uint32_t error;
102	  uint32_t stacked_r0 = BK7258_FAULT_INVALID_VALUE;
103	  uint32_t stacked_r1 = BK7258_FAULT_INVALID_VALUE;
104	  uint32_t stacked_r2 = BK7258_FAULT_INVALID_VALUE;
105	  uint32_t stacked_r3 = BK7258_FAULT_INVALID_VALUE;
106	  uint32_t stacked_r12 = BK7258_FAULT_INVALID_VALUE;
107	  uint32_t stacked_lr = BK7258_FAULT_INVALID_VALUE;
108	  uint32_t stacked_pc = BK7258_FAULT_INVALID_VALUE;
109	  uint32_t stacked_xpsr = BK7258_FAULT_INVALID_VALUE;
110	  uint32_t hfsr = BK7258_SCB_HFSR;
111	  uint32_t cfsr = BK7258_SCB_CFSR;
112	  uint32_t mmfar = BK7258_SCB_MMFAR;
113	  uint32_t bfar = BK7258_SCB_BFAR;
114	
115	  /* Hardware places the basic frame after the optional FP frame. */
116	
117	  if ((exc_return & BK7258_EXC_RETURN_BASIC_FRAME) == 0)
118	    {
119	      frame_addr += BK7258_EXCEPTION_FP_FRAME_WORDS * sizeof(uint32_t);
120	    }
121	
122	  if ((frame_addr & (sizeof(uint32_t) - 1u)) == 0 &&
123	      frame_addr >= BK7258_AP_RAM_BASE &&
124	      frame_addr <= BK7258_SHARED_RAM_BASE -
125	                    BK7258_EXCEPTION_FRAME_WORDS * sizeof(uint32_t))
126	    {
127	      frame = (const volatile uint32_t *)frame_addr;
128	      stacked_r0   = frame[0];
129	      stacked_r1   = frame[1];
130	      stacked_r2   = frame[2];
131	      stacked_r3   = frame[3];
132	      stacked_r12  = frame[4];
133	      stacked_lr   = frame[5];
134	      stacked_pc   = frame[6];
135	      stacked_xpsr = frame[7];
136	    }
137	
138	  if (exception == BK7258_EXCEPTION_NMI)
139	    {
140	      error = BK7258_AP_ERROR_NMI;
141	    }
142	  else if (exception == BK7258_EXCEPTION_HARDFAULT)
143	    {
144	      error = BK7258_AP_ERROR_HARDFAULT;
145	    }
146	  else
147	    {
148	      error = BK7258_AP_ERROR_BAD_BOOT_STATE;
149	    }
150	
151	  /* Preserve the four-word quick dump at 0x2809f070. */
152	
153	  state->reserved[0] = exception;
154	  state->reserved[1] = hfsr;
155	  state->reserved[2] = cfsr;
156	  state->reserved[3] = stacked_pc;
157	
158	  /* Publish the complete record at 0x2809f080.  Magic is written last so a
159	   * debugger never mistakes a partially populated record for a valid one.
160	   */
161	
162	  fault->magic         = 0;
163	  fault->version       = BK7258_AP_FAULT_STATE_VERSION;
164	  fault->size          = sizeof(*fault);
165	  fault->generation    = state->generation;
166	  fault->exception     = exception;
167	  fault->error         = error;
168	  fault->exc_return    = exc_return;
169	  fault->stack_pointer = (uint32_t)(uintptr_t)stack;
170	  fault->hfsr          = hfsr;
171	  fault->cfsr          = cfsr;
172	  fault->mmfar         = mmfar;
173	  fault->bfar          = bfar;
174	  fault->stacked_r0    = stacked_r0;
175	  fault->stacked_r1    = stacked_r1;
176	  fault->stacked_r2    = stacked_r2;
177	  fault->stacked_r3    = stacked_r3;
178	  fault->stacked_r12   = stacked_r12;
179	  fault->stacked_lr    = stacked_lr;
180	  fault->stacked_pc    = stacked_pc;
181	  fault->stacked_xpsr  = stacked_xpsr;
182	  __asm volatile ("dmb sy" ::: "memory");
183	  fault->magic = BK7258_AP_FAULT_STATE_MAGIC;
184	
185	  bk7258_ap_fault_doorbell(BK7258_AP_EVENT_FAILED, error);
186	
187	  for (; ; )
188	    {
189	      __asm volatile ("wfe");
190	    }
191	}
192	
193	static void __attribute__((naked, noreturn, used))
194	bk7258_ap_fault_entry(void)
195	{
196	  __asm volatile
197	    (
198	      "tst lr, #4\n"
199	      "ite eq\n"
200	      "mrseq r0, msp\n"
201	      "mrsne r0, psp\n"
202	      "mov r1, lr\n"
203	      "mrs r2, ipsr\n"
204	      "b bk7258_ap_fault_handler\n"
205	    );
206	}
