209	 * Public Data
210	 ****************************************************************************/
211	
212	__attribute__((section(".vectors_core0"), used, aligned(4)))
213	const void *const __vector_core0_table[80] =
214	{
215	  [0]       = (void *)BK7258_AP_IDLE_STACK,
216	  [1]       = (void *)bk7258_ap_reset_entry,
217	  [2 ... 3] = &bk7258_ap_fault_entry,
218	  [4 ... 79] = &exception_common
219	};
220	
221	/* NuttX ARM common code looks up _vectors.  Keep the official AP-local name
222	 * as the storage symbol and provide _vectors as an exact alias.
223	 */
224	
225	extern const void *const _vectors[80]
226	  __attribute__((alias("__vector_core0_table")));
