162	
163	int main(int argc, char *argv[])
164	{
165	  uint32_t timeout;
166	  uint32_t count;
167	  uint32_t i;
168	  int ret = -EINVAL;
169	
170	  if (argc < 2)
171	    {
172	      apctl_usage();
173	      return 1;
174	    }
175	
176	  timeout = apctl_u32(argc > 2 ? argv[2] : NULL,
177	                      BK7258_AP_DEFAULT_TIMEOUT_MS);
178	
179	  if (strcmp(argv[1], "start") == 0)
180	    {
181	      ret = bk7258_ap_start(timeout);
182	    }
183	  else if (strcmp(argv[1], "stop") == 0)
184	    {
185	      ret = bk7258_ap_stop(timeout);
186	    }
187	  else if (strcmp(argv[1], "restart") == 0)
188	    {
189	      ret = bk7258_ap_restart(timeout);
190	    }
191	  else if (strcmp(argv[1], "status") == 0)
192	    {
193	      apctl_status();
194	      return 0;
195	    }
196	  else if (strcmp(argv[1], "cycle") == 0)
197	    {
198	      count = apctl_u32(argc > 2 ? argv[2] : NULL, 3);
199	      timeout = apctl_u32(argc > 3 ? argv[3] : NULL,
200	                          BK7258_AP_DEFAULT_TIMEOUT_MS);
201	
202	      for (i = 0; i < count; i++)
203	        {
204	          ret = bk7258_ap_start(timeout);
205	          if (ret < 0)
206	            {
207	              break;
208	            }
209	
210	          apctl_status();
211	          ret = bk7258_ap_stop(timeout);
212	          if (ret < 0)
213	            {
214	              break;
215	            }
216	        }
217	    }
218	  else
219	    {
220	      apctl_usage();
221	      return 1;
222	    }
223	
224	  apctl_status();
225	  if (ret < 0)
226	    {
227	      fprintf(stderr, "apctl: %s failed: %d\n", argv[1], ret);
228	      return 1;
229	    }
230	
231	  return 0;
232	}
